-- Direct compact monthly publication. No public reader, conversion, candidate
-- cleanup, restored readiness, source eviction or scheduler authority.
-- Generated from review/generate-schema28.ts and worker/archive-compact-schema.ts.
CREATE TABLE archive_compact_builds (publication_id TEXT PRIMARY KEY,
 verification_id TEXT NOT NULL,generation TEXT NOT NULL,run_id TEXT NOT NULL,snapshot_commit_token TEXT NOT NULL,
 graph_sha256 TEXT NOT NULL CHECK(length(graph_sha256)=64 AND graph_sha256 NOT GLOB '*[^a-f0-9]*'),validator_version INTEGER NOT NULL CHECK(validator_version=1),
 archive_id TEXT NOT NULL,center_id TEXT NOT NULL,month TEXT NOT NULL,timezone TEXT NOT NULL,
 root_reference_json TEXT NOT NULL CHECK(json_valid(root_reference_json) AND json_type(root_reference_json)='object' AND length(CAST(root_reference_json AS BLOB))<=2048),
 header_json TEXT NOT NULL CHECK(json_valid(header_json) AND json_type(header_json)='object' AND length(CAST(header_json AS BLOB))<=49152),
 header_sha256 TEXT NOT NULL CHECK(length(header_sha256)=64 AND header_sha256 NOT GLOB '*[^a-f0-9]*'),
 part_count INTEGER NOT NULL CHECK(typeof(part_count)='integer' AND part_count BETWEEN 0 AND 512),
 record_count INTEGER NOT NULL CHECK(typeof(record_count)='integer' AND record_count BETWEEN 0 AND 20000),
 catalog_version INTEGER NOT NULL CHECK(catalog_version=2),
 state TEXT NOT NULL CHECK(state IN ('building','published','invalid')),
 phase TEXT NOT NULL DEFAULT 'events' CHECK(phase IN ('events','corrections','audit','complete')),
 after_key TEXT NOT NULL DEFAULT '' CHECK(length(after_key)<=210),
 verified_events INTEGER NOT NULL DEFAULT 0 CHECK(typeof(verified_events)='integer' AND verified_events BETWEEN 0 AND 20000),
 verified_corrections INTEGER NOT NULL DEFAULT 0 CHECK(typeof(verified_corrections)='integer' AND verified_corrections BETWEEN 0 AND 20000),
 verified_audits INTEGER NOT NULL DEFAULT 0 CHECK(typeof(verified_audits)='integer' AND verified_audits BETWEEN 0 AND 20000),
 revision INTEGER NOT NULL DEFAULT 0 CHECK(typeof(revision)='integer' AND revision>=0),lease_token TEXT,lease_expires_at TEXT,
 created_at TEXT NOT NULL,updated_at TEXT NOT NULL,
 CHECK((lease_token IS NULL AND lease_expires_at IS NULL) OR (state='building' AND lease_token IS NOT NULL AND lease_expires_at IS NOT NULL)),
 CHECK(verified_events<=json_extract(header_json,'$.recordCounts.attendance_events') AND verified_corrections<=json_extract(header_json,'$.recordCounts.attendance_corrections') AND verified_audits<=json_extract(header_json,'$.recordCounts.audit_entries')),
 CHECK(json_extract(header_json,'$.format') IS 'kumon-history-archive-v2' AND json_extract(header_json,'$.kind') IS 'monthly'
 AND json_type(header_json,'$.references') IS 'array' AND json_array_length(header_json,'$.references')=0
 AND json_extract(header_json,'$.archiveId') IS archive_id AND json_extract(header_json,'$.centerId') IS center_id
 AND json_extract(header_json,'$.month') IS month AND json_extract(header_json,'$.timezone') IS timezone
 AND json_extract(header_json,'$.recordCount') IS record_count
 AND json_extract(root_reference_json,'$.archiveId') IS archive_id AND json_extract(root_reference_json,'$.kind') IS 'monthly'
 AND json_type(root_reference_json,'$.manifestObjectKey') IS 'text' AND length(json_extract(root_reference_json,'$.manifestObjectKey')) BETWEEN 1 AND 1024
 AND length(json_extract(root_reference_json,'$.manifestSha256'))=64 AND json_extract(root_reference_json,'$.manifestSha256') NOT GLOB '*[^a-f0-9]*')
) WITHOUT ROWID;
CREATE UNIQUE INDEX archive_compact_month_owner ON archive_compact_builds(center_id,month) WHERE state!='invalid';
CREATE UNIQUE INDEX archive_compact_archive_owner ON archive_compact_builds(archive_id) WHERE state!='invalid';
CREATE INDEX archive_compact_build_proof ON archive_compact_builds(verification_id,generation,state);
CREATE INDEX archive_compact_build_run ON archive_compact_builds(run_id,state);
CREATE TABLE archive_compact_identities (
 publication_id TEXT PRIMARY KEY REFERENCES archive_compact_builds(publication_id),origin TEXT NOT NULL CHECK(origin='direct')
) WITHOUT ROWID;
CREATE TABLE archive_compact_requests (
 request_id TEXT PRIMARY KEY REFERENCES history_request_keys(request_id),publication_id TEXT NOT NULL REFERENCES archive_compact_identities(publication_id)
) WITHOUT ROWID;
CREATE INDEX archive_compact_request_publication ON archive_compact_requests(publication_id,request_id);
CREATE TABLE archive_compact_publications (publication_id TEXT PRIMARY KEY,
 verification_id TEXT NOT NULL,generation TEXT NOT NULL,run_id TEXT NOT NULL,snapshot_commit_token TEXT NOT NULL,
 graph_sha256 TEXT NOT NULL CHECK(length(graph_sha256)=64 AND graph_sha256 NOT GLOB '*[^a-f0-9]*'),validator_version INTEGER NOT NULL CHECK(validator_version=1),
 archive_id TEXT NOT NULL,center_id TEXT NOT NULL,month TEXT NOT NULL,timezone TEXT NOT NULL,
 root_reference_json TEXT NOT NULL CHECK(json_valid(root_reference_json) AND json_type(root_reference_json)='object' AND length(CAST(root_reference_json AS BLOB))<=2048),
 header_json TEXT NOT NULL CHECK(json_valid(header_json) AND json_type(header_json)='object' AND length(CAST(header_json AS BLOB))<=49152),
 header_sha256 TEXT NOT NULL CHECK(length(header_sha256)=64 AND header_sha256 NOT GLOB '*[^a-f0-9]*'),
 part_count INTEGER NOT NULL CHECK(typeof(part_count)='integer' AND part_count BETWEEN 0 AND 512),
 record_count INTEGER NOT NULL CHECK(typeof(record_count)='integer' AND record_count BETWEEN 0 AND 20000),
 catalog_version INTEGER NOT NULL CHECK(catalog_version=2),
 request_count INTEGER NOT NULL CHECK(typeof(request_count)='integer' AND request_count BETWEEN 0 AND record_count),
 counts_json TEXT NOT NULL CHECK(json_valid(counts_json) AND json_type(counts_json)='object' AND length(CAST(counts_json AS BLOB))<=2048),
 published_at TEXT NOT NULL,UNIQUE(archive_id),UNIQUE(center_id,month),
 FOREIGN KEY(publication_id) REFERENCES archive_compact_identities(publication_id),CHECK(json_extract(header_json,'$.format') IS 'kumon-history-archive-v2' AND json_extract(header_json,'$.kind') IS 'monthly'
 AND json_type(header_json,'$.references') IS 'array' AND json_array_length(header_json,'$.references')=0
 AND json_extract(header_json,'$.archiveId') IS archive_id AND json_extract(header_json,'$.centerId') IS center_id
 AND json_extract(header_json,'$.month') IS month AND json_extract(header_json,'$.timezone') IS timezone
 AND json_extract(header_json,'$.recordCount') IS record_count
 AND json_extract(root_reference_json,'$.archiveId') IS archive_id AND json_extract(root_reference_json,'$.kind') IS 'monthly'
 AND json_type(root_reference_json,'$.manifestObjectKey') IS 'text' AND length(json_extract(root_reference_json,'$.manifestObjectKey')) BETWEEN 1 AND 1024
 AND length(json_extract(root_reference_json,'$.manifestSha256'))=64 AND json_extract(root_reference_json,'$.manifestSha256') NOT GLOB '*[^a-f0-9]*')
) WITHOUT ROWID;
CREATE TABLE archive_compact_availability (
 publication_id TEXT PRIMARY KEY REFERENCES archive_compact_publications(publication_id),generation TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('ready','unavailable'))
) WITHOUT ROWID;

CREATE TRIGGER archive_compact_build_insert BEFORE INSERT ON archive_compact_builds
WHEN EXISTS(SELECT 1 FROM archive_compact_builds WHERE publication_id=NEW.publication_id)
 OR NEW.state!='building' OR NEW.phase!='events' OR NEW.after_key!='' OR NEW.verified_events!=0 OR NEW.verified_corrections!=0 OR NEW.verified_audits!=0
 OR NEW.revision!=0 OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.created_at!=strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NEW.updated_at IS NOT NEW.created_at
 OR NOT (EXISTS(SELECT 1 FROM archive_semantic_runs pr
    JOIN archive_semantic_sessions ps ON ps.verification_id=pr.verification_id AND ps.generation=pr.generation
    JOIN archive_semantic_manifests pm ON pm.verification_id=ps.verification_id AND pm.generation=ps.generation AND pm.archive_id=pr.archive_id
    JOIN archive_semantic_lifecycle pl ON pl.verification_id=ps.verification_id AND pl.generation=ps.generation
    JOIN history_runtime ph ON ph.id=1 AND ph.generation=ps.generation WHERE ((((pr.run_id=NEW.run_id AND (pr.verification_id=NEW.verification_id AND pr.generation=NEW.generation)) AND (pr.snapshot_commit_token=NEW.snapshot_commit_token AND (pr.graph_sha256=NEW.graph_sha256 AND pr.validator_version=NEW.validator_version))) AND ((pr.validator_version=1 AND (pr.status='complete' AND pr.phase='complete')) AND (pr.archive_id=NEW.archive_id AND (pr.header_json=NEW.header_json AND ps.status='verified')))) AND (((ps.commit_token=NEW.snapshot_commit_token AND (ps.graph_sha256=NEW.graph_sha256 AND ps.root_archive_id=NEW.archive_id)) AND (ps.root_reference_json=NEW.root_reference_json AND (pm.manifest_sha256=ps.root_manifest_sha256 AND pm.manifest_sha256=json_extract(NEW.root_reference_json,'$.manifestSha256')))) AND ((pm.part_count=NEW.part_count AND (pm.record_count=NEW.record_count AND json_remove(pm.manifest_json,'$.parts')=NEW.header_json)) AND (ph.state='ready' AND (pl.pause_reason IS NULL AND pl.due_at>strftime('%Y-%m-%dT%H:%M:%fZ','now'))))))))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_PROOF_INVALID'); END;

CREATE TRIGGER archive_compact_build_legacy_conflict BEFORE INSERT ON archive_compact_builds
WHEN EXISTS(SELECT 1 FROM archive_publication_builds v WHERE v.publication_id=NEW.publication_id OR (v.state!='invalid' AND (v.archive_id=NEW.archive_id OR (v.center_id=NEW.center_id AND v.month=NEW.month))))
 OR EXISTS(SELECT 1 FROM archive_publications v WHERE v.publication_id=NEW.publication_id OR v.archive_id=NEW.archive_id OR (v.center_id=NEW.center_id AND v.month=NEW.month))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_CROSS_FORMAT_CONFLICT'); END;

CREATE TRIGGER archive_legacy_build_compact_conflict BEFORE INSERT ON archive_publication_builds
WHEN EXISTS(SELECT 1 FROM archive_compact_builds c WHERE c.publication_id=NEW.publication_id OR (c.state!='invalid' AND (c.archive_id=NEW.archive_id OR (c.center_id=NEW.center_id AND c.month=NEW.month))))
 OR EXISTS(SELECT 1 FROM archive_compact_publications c WHERE c.publication_id=NEW.publication_id OR c.archive_id=NEW.archive_id OR (c.center_id=NEW.center_id AND c.month=NEW.month))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_CROSS_FORMAT_CONFLICT'); END;

CREATE TRIGGER archive_legacy_descriptor_compact_conflict BEFORE INSERT ON archive_publications
WHEN EXISTS(SELECT 1 FROM archive_compact_builds c WHERE c.publication_id=NEW.publication_id OR (c.state!='invalid' AND (c.archive_id=NEW.archive_id OR (c.center_id=NEW.center_id AND c.month=NEW.month))))
 OR EXISTS(SELECT 1 FROM archive_compact_publications c WHERE c.publication_id=NEW.publication_id OR c.archive_id=NEW.archive_id OR (c.center_id=NEW.center_id AND c.month=NEW.month))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_CROSS_FORMAT_CONFLICT'); END;

CREATE TRIGGER archive_compact_build_identity AFTER INSERT ON archive_compact_builds BEGIN INSERT INTO archive_compact_identities(publication_id,origin) VALUES(NEW.publication_id,'direct'); END;

CREATE TRIGGER archive_compact_identity_insert BEFORE INSERT ON archive_compact_identities
WHEN EXISTS(SELECT 1 FROM archive_compact_identities WHERE publication_id=NEW.publication_id) OR NOT EXISTS(SELECT 1 FROM archive_compact_builds b WHERE b.publication_id=NEW.publication_id AND b.state='building' AND b.phase='events' AND b.revision=0 AND EXISTS(SELECT 1 FROM archive_semantic_runs pr
    JOIN archive_semantic_sessions ps ON ps.verification_id=pr.verification_id AND ps.generation=pr.generation
    JOIN archive_semantic_manifests pm ON pm.verification_id=ps.verification_id AND pm.generation=ps.generation AND pm.archive_id=pr.archive_id
    JOIN archive_semantic_lifecycle pl ON pl.verification_id=ps.verification_id AND pl.generation=ps.generation
    JOIN history_runtime ph ON ph.id=1 AND ph.generation=ps.generation WHERE ((((pr.run_id=b.run_id AND (pr.verification_id=b.verification_id AND pr.generation=b.generation)) AND (pr.snapshot_commit_token=b.snapshot_commit_token AND (pr.graph_sha256=b.graph_sha256 AND pr.validator_version=b.validator_version))) AND ((pr.validator_version=1 AND (pr.status='complete' AND pr.phase='complete')) AND (pr.archive_id=b.archive_id AND (pr.header_json=b.header_json AND ps.status='verified')))) AND (((ps.commit_token=b.snapshot_commit_token AND (ps.graph_sha256=b.graph_sha256 AND ps.root_archive_id=b.archive_id)) AND (ps.root_reference_json=b.root_reference_json AND (pm.manifest_sha256=ps.root_manifest_sha256 AND pm.manifest_sha256=json_extract(b.root_reference_json,'$.manifestSha256')))) AND ((pm.part_count=b.part_count AND (pm.record_count=b.record_count AND json_remove(pm.manifest_json,'$.parts')=b.header_json)) AND (ph.state='ready' AND (pl.pause_reason IS NULL AND pl.due_at>strftime('%Y-%m-%dT%H:%M:%fZ','now'))))))))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_IDENTITY_INVALID'); END;

CREATE TRIGGER archive_compact_build_update BEFORE UPDATE ON archive_compact_builds
WHEN NOT (((((NEW.publication_id IS OLD.publication_id AND NEW.verification_id IS OLD.verification_id) AND (NEW.generation IS OLD.generation AND NEW.run_id IS OLD.run_id)) AND ((NEW.snapshot_commit_token IS OLD.snapshot_commit_token AND NEW.graph_sha256 IS OLD.graph_sha256) AND (NEW.validator_version IS OLD.validator_version AND (NEW.archive_id IS OLD.archive_id AND NEW.center_id IS OLD.center_id)))) AND (((NEW.month IS OLD.month AND NEW.timezone IS OLD.timezone) AND (NEW.root_reference_json IS OLD.root_reference_json AND NEW.header_json IS OLD.header_json)) AND ((NEW.header_sha256 IS OLD.header_sha256 AND NEW.part_count IS OLD.part_count) AND (NEW.record_count IS OLD.record_count AND (NEW.catalog_version IS OLD.catalog_version AND NEW.created_at IS OLD.created_at)))))) OR NEW.revision!=OLD.revision+1 OR NEW.updated_at!=strftime('%Y-%m-%dT%H:%M:%fZ','now')
 OR NOT COALESCE(CASE
 WHEN OLD.state!='building' THEN 0
 WHEN NEW.state='invalid' THEN (((NEW.phase IS OLD.phase AND NEW.after_key IS OLD.after_key) AND (NEW.verified_events IS OLD.verified_events AND (NEW.verified_corrections IS OLD.verified_corrections AND NEW.verified_audits IS OLD.verified_audits))) AND NEW.lease_token IS NULL AND NEW.lease_expires_at IS NULL AND NOT (EXISTS(SELECT 1 FROM archive_semantic_runs pr
    JOIN archive_semantic_sessions ps ON ps.verification_id=pr.verification_id AND ps.generation=pr.generation
    JOIN archive_semantic_manifests pm ON pm.verification_id=ps.verification_id AND pm.generation=ps.generation AND pm.archive_id=pr.archive_id
    JOIN archive_semantic_lifecycle pl ON pl.verification_id=ps.verification_id AND pl.generation=ps.generation
    JOIN history_runtime ph ON ph.id=1 AND ph.generation=ps.generation WHERE ((((pr.run_id=OLD.run_id AND (pr.verification_id=OLD.verification_id AND pr.generation=OLD.generation)) AND (pr.snapshot_commit_token=OLD.snapshot_commit_token AND (pr.graph_sha256=OLD.graph_sha256 AND pr.validator_version=OLD.validator_version))) AND ((pr.validator_version=1 AND (pr.status='complete' AND pr.phase='complete')) AND (pr.archive_id=OLD.archive_id AND (pr.header_json=OLD.header_json AND ps.status='verified')))) AND (((ps.commit_token=OLD.snapshot_commit_token AND (ps.graph_sha256=OLD.graph_sha256 AND ps.root_archive_id=OLD.archive_id)) AND (ps.root_reference_json=OLD.root_reference_json AND (pm.manifest_sha256=ps.root_manifest_sha256 AND pm.manifest_sha256=json_extract(OLD.root_reference_json,'$.manifestSha256')))) AND ((pm.part_count=OLD.part_count AND (pm.record_count=OLD.record_count AND json_remove(pm.manifest_json,'$.parts')=OLD.header_json)) AND (ph.state='ready' AND (pl.pause_reason IS NULL AND pl.due_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')))))))))
 WHEN NEW.state='published' THEN (((NEW.phase IS OLD.phase AND NEW.after_key IS OLD.after_key) AND (NEW.verified_events IS OLD.verified_events AND (NEW.verified_corrections IS OLD.verified_corrections AND NEW.verified_audits IS OLD.verified_audits))) AND NEW.phase='complete' AND NEW.lease_token IS NULL AND NEW.lease_expires_at IS NULL AND ((OLD.state='building' AND OLD.lease_token IS NOT NULL) AND (OLD.lease_expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (EXISTS(SELECT 1 FROM archive_semantic_runs pr
    JOIN archive_semantic_sessions ps ON ps.verification_id=pr.verification_id AND ps.generation=pr.generation
    JOIN archive_semantic_manifests pm ON pm.verification_id=ps.verification_id AND pm.generation=ps.generation AND pm.archive_id=pr.archive_id
    JOIN archive_semantic_lifecycle pl ON pl.verification_id=ps.verification_id AND pl.generation=ps.generation
    JOIN history_runtime ph ON ph.id=1 AND ph.generation=ps.generation WHERE ((((pr.run_id=OLD.run_id AND (pr.verification_id=OLD.verification_id AND pr.generation=OLD.generation)) AND (pr.snapshot_commit_token=OLD.snapshot_commit_token AND (pr.graph_sha256=OLD.graph_sha256 AND pr.validator_version=OLD.validator_version))) AND ((pr.validator_version=1 AND (pr.status='complete' AND pr.phase='complete')) AND (pr.archive_id=OLD.archive_id AND (pr.header_json=OLD.header_json AND ps.status='verified')))) AND (((ps.commit_token=OLD.snapshot_commit_token AND (ps.graph_sha256=OLD.graph_sha256 AND ps.root_archive_id=OLD.archive_id)) AND (ps.root_reference_json=OLD.root_reference_json AND (pm.manifest_sha256=ps.root_manifest_sha256 AND pm.manifest_sha256=json_extract(OLD.root_reference_json,'$.manifestSha256')))) AND ((pm.part_count=OLD.part_count AND (pm.record_count=OLD.record_count AND json_remove(pm.manifest_json,'$.parts')=OLD.header_json)) AND (ph.state='ready' AND (pl.pause_reason IS NULL AND pl.due_at>strftime('%Y-%m-%dT%H:%M:%fZ','now'))))))) AND NOT EXISTS(SELECT 1 FROM backup_runtime WHERE id=1 AND write_locked_until>strftime('%Y-%m-%dT%H:%M:%fZ','now')))))
   AND OLD.verified_events=json_extract(OLD.header_json,'$.recordCounts.attendance_events') AND OLD.verified_corrections=json_extract(OLD.header_json,'$.recordCounts.attendance_corrections') AND OLD.verified_audits=json_extract(OLD.header_json,'$.recordCounts.audit_entries') AND NOT EXISTS(SELECT 1 FROM archive_semantic_rows sr WHERE sr.verification_id=OLD.verification_id AND sr.generation=OLD.generation AND sr.archive_id=OLD.archive_id AND sr.table_name IN ('attendance_events','attendance_corrections')
    AND NOT EXISTS(SELECT 1 FROM archive_compact_requests q WHERE q.request_id=sr.record_key AND q.publication_id=OLD.publication_id))
    AND NOT EXISTS(SELECT 1 FROM archive_compact_requests q JOIN history_request_keys k ON k.request_id=q.request_id
