    AND (SELECT count(*) FROM archive_compact_requests q WHERE q.publication_id=OLD.publication_id)=OLD.verified_events+OLD.verified_corrections AND EXISTS(SELECT 1 FROM archive_compact_publications p WHERE p.publication_id=OLD.publication_id AND ((((p.publication_id IS OLD.publication_id AND p.verification_id IS OLD.verification_id) AND (p.generation IS OLD.generation AND p.run_id IS OLD.run_id)) AND ((p.snapshot_commit_token IS OLD.snapshot_commit_token AND p.graph_sha256 IS OLD.graph_sha256) AND (p.validator_version IS OLD.validator_version AND p.archive_id IS OLD.archive_id))) AND (((p.center_id IS OLD.center_id AND p.month IS OLD.month) AND (p.timezone IS OLD.timezone AND p.root_reference_json IS OLD.root_reference_json)) AND ((p.header_json IS OLD.header_json AND p.header_sha256 IS OLD.header_sha256) AND (p.part_count IS OLD.part_count AND (p.record_count IS OLD.record_count AND p.catalog_version IS OLD.catalog_version)))))))
 WHEN NEW.state='building' THEN CASE
  WHEN NEW.lease_token IS NOT NULL THEN (((NEW.phase IS OLD.phase AND NEW.after_key IS OLD.after_key) AND (NEW.verified_events IS OLD.verified_events AND (NEW.verified_corrections IS OLD.verified_corrections AND NEW.verified_audits IS OLD.verified_audits))) AND EXISTS(SELECT 1 FROM archive_semantic_runs pr
    JOIN archive_semantic_sessions ps ON ps.verification_id=pr.verification_id AND ps.generation=pr.generation
