    JOIN archive_semantic_lifecycle pl ON pl.verification_id=ps.verification_id AND pl.generation=ps.generation
    JOIN history_runtime ph ON ph.id=1 AND ph.generation=ps.generation WHERE ((((pr.run_id=OLD.run_id AND (pr.verification_id=OLD.verification_id AND pr.generation=OLD.generation)) AND (pr.snapshot_commit_token=OLD.snapshot_commit_token AND (pr.graph_sha256=OLD.graph_sha256 AND pr.validator_version=OLD.validator_version))) AND ((pr.validator_version=1 AND (pr.status='complete' AND pr.phase='complete')) AND (pr.archive_id=OLD.archive_id AND (pr.header_json=OLD.header_json AND ps.status='verified')))) AND (((ps.commit_token=OLD.snapshot_commit_token AND (ps.graph_sha256=OLD.graph_sha256 AND ps.root_archive_id=OLD.archive_id)) AND (ps.root_reference_json=OLD.root_reference_json AND (pm.manifest_sha256=ps.root_manifest_sha256 AND pm.manifest_sha256=json_extract(OLD.root_reference_json,'$.manifestSha256')))) AND ((pm.part_count=OLD.part_count AND (pm.record_count=OLD.record_count AND json_remove(pm.manifest_json,'$.parts')=OLD.header_json)) AND (ph.state='ready' AND (pl.pause_reason IS NULL AND pl.due_at>strftime('%Y-%m-%dT%H:%M:%fZ','now'))))))) AND NOT EXISTS(SELECT 1 FROM backup_runtime WHERE id=1 AND write_locked_until>strftime('%Y-%m-%dT%H:%M:%fZ','now'))
   AND (OLD.lease_token IS NULL OR OLD.lease_expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND length(NEW.lease_token) BETWEEN 1 AND 100
   AND NEW.lease_expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND NEW.lease_expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now','+30 seconds'))
  ELSE (NEW.lease_expires_at IS NULL AND OLD.lease_token IS NOT NULL AND ((((NEW.phase IS OLD.phase AND NEW.after_key IS OLD.after_key) AND (NEW.verified_events IS OLD.verified_events AND (NEW.verified_corrections IS OLD.verified_corrections AND NEW.verified_audits IS OLD.verified_audits)))) OR (((OLD.state='building' AND OLD.lease_token IS NOT NULL) AND (OLD.lease_expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (EXISTS(SELECT 1 FROM archive_semantic_runs pr
    JOIN archive_semantic_sessions ps ON ps.verification_id=pr.verification_id AND ps.generation=pr.generation
    JOIN archive_semantic_manifests pm ON pm.verification_id=ps.verification_id AND pm.generation=ps.generation AND pm.archive_id=pr.archive_id
