    AND k.source_kind='event' AND k.center_id=s.center_id AND k.payload_hash IS s.payload_hash AND k.hash_encoding=(CASE WHEN length(s.payload_hash)=64 AND s.payload_hash NOT GLOB '*[^a-fA-F0-9]*' THEN 'hex-sha256'
    WHEN length(s.payload_hash)=44 AND substr(s.payload_hash,44,1)='=' AND substr(s.payload_hash,1,43) NOT GLOB '*[^A-Za-z0-9+/]*' THEN 'base64-sha256'
    WHEN length(s.payload_hash)=43 AND s.payload_hash NOT GLOB '*[^A-Za-z0-9_-]*' THEN 'base64url-sha256' ELSE 'opaque' END) AND k.canonicalization='legacy-unverified')
      WHEN 'attendance_corrections' THEN EXISTS(SELECT 1 FROM attendance_corrections s JOIN history_request_keys k ON k.request_id=s.id WHERE (s.id=sr.record_key AND (s.center_id=b.center_id AND (((s.id IS json_extract(sr.record_json,'$.row.id') AND (s.center_id IS json_extract(sr.record_json,'$.row.center_id') AND s.visit_id IS json_extract(sr.record_json,'$.row.visit_id'))) AND (s.expected_version IS json_extract(sr.record_json,'$.row.expected_version') AND (s.prior_check_in_at IS json_extract(sr.record_json,'$.row.prior_check_in_at') AND s.prior_check_out_at IS json_extract(sr.record_json,'$.row.prior_check_out_at')))) AND ((s.check_in_at IS json_extract(sr.record_json,'$.row.check_in_at') AND (s.check_out_at IS json_extract(sr.record_json,'$.row.check_out_at') AND s.reason IS json_extract(sr.record_json,'$.row.reason'))) AND ((s.actor_id IS json_extract(sr.record_json,'$.row.actor_id') AND s.actor_name IS json_extract(sr.record_json,'$.row.actor_name')) AND (s.recorded_at IS json_extract(sr.record_json,'$.row.recorded_at') AND s.payload_hash IS json_extract(sr.record_json,'$.row.payload_hash'))))))) AND EXISTS(SELECT 1 FROM visits v WHERE v.id=s.visit_id AND v.center_id=s.center_id AND v.original_check_in_at>=json_extract(b.header_json,'$.periodFrom') AND v.original_check_in_at<json_extract(b.header_json,'$.periodTo'))
    AND k.source_kind='correction' AND k.center_id=s.center_id AND k.payload_hash IS s.payload_hash AND k.hash_encoding=(CASE WHEN length(s.payload_hash)=64 AND s.payload_hash NOT GLOB '*[^a-fA-F0-9]*' THEN 'hex-sha256'
    WHEN length(s.payload_hash)=44 AND substr(s.payload_hash,44,1)='=' AND substr(s.payload_hash,1,43) NOT GLOB '*[^A-Za-z0-9+/]*' THEN 'base64-sha256'
    WHEN length(s.payload_hash)=43 AND s.payload_hash NOT GLOB '*[^A-Za-z0-9_-]*' THEN 'base64url-sha256' ELSE 'opaque' END) AND k.canonicalization='legacy-unverified')
      WHEN 'audit_entries' THEN (EXISTS(SELECT 1 FROM audit_entries s WHERE (s.id=sr.record_key AND (s.center_id=b.center_id AND (((s.id IS json_extract(sr.record_json,'$.row.id') AND s.center_id IS json_extract(sr.record_json,'$.row.center_id')) AND (s.actor_id IS json_extract(sr.record_json,'$.row.actor_id') AND s.actor_name IS json_extract(sr.record_json,'$.row.actor_name'))) AND ((s.action IS json_extract(sr.record_json,'$.row.action') AND s.entity_type IS json_extract(sr.record_json,'$.row.entity_type')) AND (s.entity_id IS json_extract(sr.record_json,'$.row.entity_id') AND (s.detail IS json_extract(sr.record_json,'$.row.detail') AND s.created_at IS json_extract(sr.record_json,'$.row.created_at')))))))) OR (NOT EXISTS(SELECT 1 FROM audit_entries a WHERE a.id=sr.record_key) AND (EXISTS(SELECT 1 FROM attendance_events e WHERE ((((e.id=sr.record_key AND (e.center_id=b.center_id AND json_extract(sr.record_json,'$.row.id') IS e.id)) AND (json_extract(sr.record_json,'$.row.center_id') IS e.center_id AND (json_extract(sr.record_json,'$.row.actor_id') IS e.actor_id AND json_extract(sr.record_json,'$.row.actor_name') IS e.actor_name))) AND (json_extract(sr.record_json,'$.row.action') IS e.action AND json_extract(sr.record_json,'$.row.entity_type') IS 'attendance_event')) AND (json_extract(sr.record_json,'$.row.entity_id') IS e.id AND (json_extract(sr.record_json,'$.row.detail') IS CAST(json_object('studentId',e.student_id,'observedAt',e.observed_at,'receivedAt',e.received_at,'channel',e.channel,'deviceId',e.device_id) AS TEXT) AND json_extract(sr.record_json,'$.row.created_at') IS e.received_at)))) OR EXISTS(SELECT 1 FROM attendance_corrections c WHERE ((((c.id=sr.record_key AND (c.center_id=b.center_id AND json_extract(sr.record_json,'$.row.id') IS c.id)) AND (json_extract(sr.record_json,'$.row.center_id') IS c.center_id AND (json_extract(sr.record_json,'$.row.actor_id') IS c.actor_id AND json_extract(sr.record_json,'$.row.actor_name') IS c.actor_name))) AND (json_extract(sr.record_json,'$.row.action') IS 'attendance_correction' AND json_extract(sr.record_json,'$.row.entity_type') IS 'visit')) AND (json_extract(sr.record_json,'$.row.entity_id') IS c.visit_id AND (json_extract(sr.record_json,'$.row.detail') IS CAST(json_object('reason',c.reason,'priorCheckInAt',c.prior_check_in_at,'priorCheckOutAt',c.prior_check_out_at,'checkInAt',c.check_in_at,'checkOutAt',c.check_out_at) AS TEXT) AND json_extract(sr.record_json,'$.row.created_at') IS c.recorded_at)))) OR EXISTS(SELECT 1 FROM history_correction_outbox c WHERE ((((c.id=sr.record_key AND (c.center_id=b.center_id AND json_extract(sr.record_json,'$.row.id') IS c.id)) AND (json_extract(sr.record_json,'$.row.center_id') IS c.center_id AND (json_extract(sr.record_json,'$.row.actor_id') IS c.actor_id AND json_extract(sr.record_json,'$.row.actor_name') IS c.actor_name))) AND (json_extract(sr.record_json,'$.row.action') IS 'attendance_correction' AND json_extract(sr.record_json,'$.row.entity_type') IS 'visit')) AND (json_extract(sr.record_json,'$.row.entity_id') IS c.visit_id AND (json_extract(sr.record_json,'$.row.detail') IS CAST(json_object('reason',c.reason,'priorCheckInAt',c.prior_check_in_at,'priorCheckOutAt',c.prior_check_out_at,'checkInAt',c.check_in_at,'checkOutAt',c.check_out_at) AS TEXT) AND json_extract(sr.record_json,'$.row.created_at') IS c.recorded_at))))))) ELSE 0 END AS source_valid
    FROM archive_semantic_rows sr JOIN archive_semantic_parts sp ON sp.verification_id=sr.verification_id AND sp.generation=sr.generation AND sp.archive_id=sr.archive_id AND sp.part_index=sr.part_index AND sp.commit_token=sr.part_commit_token
    WHERE sr.verification_id=b.verification_id AND sr.generation=b.generation AND sr.archive_id=b.archive_id
      AND sr.table_name=(CASE b.phase WHEN 'events' THEN 'attendance_events' WHEN 'corrections' THEN 'attendance_corrections' WHEN 'audit' THEN 'audit_entries' END) AND sr.record_key>b.after_key ORDER BY sr.record_key LIMIT 8) page WHERE page.record_key=NEW.request_id AND page.source_valid=1))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_REQUEST_INVALID'); END;

CREATE TRIGGER archive_legacy_request_compact_conflict BEFORE INSERT ON archive_publication_requests
WHEN EXISTS(SELECT 1 FROM archive_compact_requests WHERE request_id=NEW.request_id)
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_CROSS_FORMAT_CONFLICT'); END;

CREATE TRIGGER archive_compact_descriptor_insert BEFORE INSERT ON archive_compact_publications
WHEN EXISTS(SELECT 1 FROM archive_compact_publications WHERE publication_id=NEW.publication_id)
 OR NEW.published_at!=strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM archive_compact_builds b JOIN archive_compact_identities i ON i.publication_id=b.publication_id AND i.origin='direct'
 WHERE b.publication_id=NEW.publication_id AND ((((NEW.publication_id IS b.publication_id AND NEW.verification_id IS b.verification_id) AND (NEW.generation IS b.generation AND NEW.run_id IS b.run_id)) AND ((NEW.snapshot_commit_token IS b.snapshot_commit_token AND NEW.graph_sha256 IS b.graph_sha256) AND (NEW.validator_version IS b.validator_version AND NEW.archive_id IS b.archive_id))) AND (((NEW.center_id IS b.center_id AND NEW.month IS b.month) AND (NEW.timezone IS b.timezone AND NEW.root_reference_json IS b.root_reference_json)) AND ((NEW.header_json IS b.header_json AND NEW.header_sha256 IS b.header_sha256) AND (NEW.part_count IS b.part_count AND (NEW.record_count IS b.record_count AND NEW.catalog_version IS b.catalog_version))))) AND ((b.state='building' AND b.lease_token IS NOT NULL) AND (b.lease_expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (EXISTS(SELECT 1 FROM archive_semantic_runs pr
    JOIN archive_semantic_sessions ps ON ps.verification_id=pr.verification_id AND ps.generation=pr.generation
    JOIN archive_semantic_manifests pm ON pm.verification_id=ps.verification_id AND pm.generation=ps.generation AND pm.archive_id=pr.archive_id
    JOIN archive_semantic_lifecycle pl ON pl.verification_id=ps.verification_id AND pl.generation=ps.generation
    JOIN history_runtime ph ON ph.id=1 AND ph.generation=ps.generation WHERE ((((pr.run_id=b.run_id AND (pr.verification_id=b.verification_id AND pr.generation=b.generation)) AND (pr.snapshot_commit_token=b.snapshot_commit_token AND (pr.graph_sha256=b.graph_sha256 AND pr.validator_version=b.validator_version))) AND ((pr.validator_version=1 AND (pr.status='complete' AND pr.phase='complete')) AND (pr.archive_id=b.archive_id AND (pr.header_json=b.header_json AND ps.status='verified')))) AND (((ps.commit_token=b.snapshot_commit_token AND (ps.graph_sha256=b.graph_sha256 AND ps.root_archive_id=b.archive_id)) AND (ps.root_reference_json=b.root_reference_json AND (pm.manifest_sha256=ps.root_manifest_sha256 AND pm.manifest_sha256=json_extract(b.root_reference_json,'$.manifestSha256')))) AND ((pm.part_count=b.part_count AND (pm.record_count=b.record_count AND json_remove(pm.manifest_json,'$.parts')=b.header_json)) AND (ph.state='ready' AND (pl.pause_reason IS NULL AND pl.due_at>strftime('%Y-%m-%dT%H:%M:%fZ','now'))))))) AND NOT EXISTS(SELECT 1 FROM backup_runtime WHERE id=1 AND write_locked_until>strftime('%Y-%m-%dT%H:%M:%fZ','now')))))
 AND b.phase='complete' AND b.after_key='' AND b.verified_events=json_extract(b.header_json,'$.recordCounts.attendance_events') AND b.verified_corrections=json_extract(b.header_json,'$.recordCounts.attendance_corrections') AND b.verified_audits=json_extract(b.header_json,'$.recordCounts.audit_entries') AND NOT EXISTS(SELECT 1 FROM archive_semantic_rows sr WHERE sr.verification_id=b.verification_id AND sr.generation=b.generation AND sr.archive_id=b.archive_id AND sr.table_name IN ('attendance_events','attendance_corrections')
    AND NOT EXISTS(SELECT 1 FROM archive_compact_requests q WHERE q.request_id=sr.record_key AND q.publication_id=b.publication_id))
    AND NOT EXISTS(SELECT 1 FROM archive_compact_requests q JOIN history_request_keys k ON k.request_id=q.request_id
      WHERE q.publication_id=b.publication_id AND NOT (k.center_id=b.center_id AND (
        (k.source_kind='event' AND EXISTS(SELECT 1 FROM archive_semantic_rows sr
          WHERE sr.verification_id=b.verification_id AND sr.generation=b.generation AND sr.archive_id=b.archive_id
          AND sr.table_name='attendance_events' AND sr.record_key=q.request_id AND k.payload_hash IS json_extract(sr.record_json,'$.row.payload_hash')))
        OR (k.source_kind='correction' AND EXISTS(SELECT 1 FROM archive_semantic_rows sr
          WHERE sr.verification_id=b.verification_id AND sr.generation=b.generation AND sr.archive_id=b.archive_id
          AND sr.table_name='attendance_corrections' AND sr.record_key=q.request_id AND k.payload_hash IS json_extract(sr.record_json,'$.row.payload_hash'))))))
    AND (SELECT count(*) FROM archive_compact_requests q WHERE q.publication_id=b.publication_id)=b.verified_events+b.verified_corrections
 AND NEW.request_count=b.verified_events+b.verified_corrections AND NEW.counts_json IS json_extract(b.header_json,'$.recordCounts'))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_DESCRIPTOR_INVALID'); END;

CREATE TRIGGER archive_compact_descriptor_commit AFTER INSERT ON archive_compact_publications BEGIN
 UPDATE archive_compact_builds SET state='published',revision=revision+1,lease_token=NULL,lease_expires_at=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE publication_id=NEW.publication_id;
 INSERT INTO archive_compact_availability(publication_id,generation,status) VALUES(NEW.publication_id,NEW.generation,'ready');
END;

CREATE TRIGGER archive_compact_availability_insert BEFORE INSERT ON archive_compact_availability
WHEN EXISTS(SELECT 1 FROM archive_compact_availability WHERE publication_id=NEW.publication_id)
 OR NEW.status!='ready' OR NOT EXISTS(SELECT 1 FROM archive_compact_publications p JOIN archive_compact_builds b ON b.publication_id=p.publication_id
 WHERE p.publication_id=NEW.publication_id AND b.state='published' AND p.generation=NEW.generation AND ((((p.publication_id IS b.publication_id AND p.verification_id IS b.verification_id) AND (p.generation IS b.generation AND p.run_id IS b.run_id)) AND ((p.snapshot_commit_token IS b.snapshot_commit_token AND p.graph_sha256 IS b.graph_sha256) AND (p.validator_version IS b.validator_version AND p.archive_id IS b.archive_id))) AND (((p.center_id IS b.center_id AND p.month IS b.month) AND (p.timezone IS b.timezone AND p.root_reference_json IS b.root_reference_json)) AND ((p.header_json IS b.header_json AND p.header_sha256 IS b.header_sha256) AND (p.part_count IS b.part_count AND (p.record_count IS b.record_count AND p.catalog_version IS b.catalog_version))))) AND EXISTS(SELECT 1 FROM archive_semantic_runs pr
    JOIN archive_semantic_sessions ps ON ps.verification_id=pr.verification_id AND ps.generation=pr.generation
    JOIN archive_semantic_manifests pm ON pm.verification_id=ps.verification_id AND pm.generation=ps.generation AND pm.archive_id=pr.archive_id
    JOIN archive_semantic_lifecycle pl ON pl.verification_id=ps.verification_id AND pl.generation=ps.generation
    JOIN history_runtime ph ON ph.id=1 AND ph.generation=ps.generation WHERE ((((pr.run_id=b.run_id AND (pr.verification_id=b.verification_id AND pr.generation=b.generation)) AND (pr.snapshot_commit_token=b.snapshot_commit_token AND (pr.graph_sha256=b.graph_sha256 AND pr.validator_version=b.validator_version))) AND ((pr.validator_version=1 AND (pr.status='complete' AND pr.phase='complete')) AND (pr.archive_id=b.archive_id AND (pr.header_json=b.header_json AND ps.status='verified')))) AND (((ps.commit_token=b.snapshot_commit_token AND (ps.graph_sha256=b.graph_sha256 AND ps.root_archive_id=b.archive_id)) AND (ps.root_reference_json=b.root_reference_json AND (pm.manifest_sha256=ps.root_manifest_sha256 AND pm.manifest_sha256=json_extract(b.root_reference_json,'$.manifestSha256')))) AND ((pm.part_count=b.part_count AND (pm.record_count=b.record_count AND json_remove(pm.manifest_json,'$.parts')=b.header_json)) AND (ph.state='ready' AND (pl.pause_reason IS NULL AND pl.due_at>strftime('%Y-%m-%dT%H:%M:%fZ','now'))))))))
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_AVAILABILITY_INVALID'); END;

CREATE TRIGGER archive_compact_availability_update BEFORE UPDATE ON archive_compact_availability
WHEN NEW.publication_id IS NOT OLD.publication_id OR NEW.status!='unavailable' OR NOT EXISTS(SELECT 1 FROM history_runtime h WHERE h.id=1 AND h.generation=NEW.generation)
BEGIN SELECT RAISE(ABORT,'ARCHIVE_COMPACT_AVAILABILITY_INVALID'); END;

CREATE TRIGGER archive_compact_generation_reset AFTER UPDATE OF generation ON history_runtime WHEN NEW.generation!=OLD.generation BEGIN
 UPDATE archive_compact_builds SET state='invalid',revision=revision+1,lease_token=NULL,lease_expires_at=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE state='building';
 UPDATE archive_compact_availability SET generation=NEW.generation,status='unavailable';
END;
CREATE TRIGGER archive_compact_session_invalidated AFTER UPDATE OF status ON archive_semantic_sessions WHEN NEW.status='invalid' BEGIN
 UPDATE archive_compact_builds SET state='invalid',revision=revision+1,lease_token=NULL,lease_expires_at=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE verification_id=NEW.verification_id AND generation=NEW.generation AND state='building';
END;
CREATE TRIGGER archive_compact_run_invalidated AFTER UPDATE OF status ON archive_semantic_runs WHEN NEW.status='invalid' BEGIN
 UPDATE archive_compact_builds SET state='invalid',revision=revision+1,lease_token=NULL,lease_expires_at=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE run_id=NEW.run_id AND state='building';
END;

